import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.CAfGEm1x.js";const u=JSON.parse('{"title":"Contributing to kundol","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md"}'),n={name:"contributing.md"};function r(o,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="contributing-to-kundol" tabindex="-1">Contributing to kundol <a class="header-anchor" href="#contributing-to-kundol" aria-label="Permalink to &quot;Contributing to kundol&quot;">​</a></h1><p>Last updated: 2026-09-15 16:06:28 IST Related tasks: <code>KUN-088</code>, <code>KUN-093</code>, <code>KUN-097</code>, <code>KUN-103</code></p><p>kundol is a Bun + TypeScript CLI. Start with the <a href="https://github.com/vikz91/kundol/blob/main/docs/context.md" target="_blank" rel="noreferrer">current code map</a> and <a href="https://github.com/vikz91/kundol/blob/main/docs/agents.md" target="_blank" rel="noreferrer">agent guide</a>; older dashboard and indexing docs describe retired commands and implementations.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Keep CLI behavior, tests, and docs in step. For cleanup changes, show the scanned plan before any apply path, recheck live targets, and test against temporary homes and workdirs. Never run destructive smoke tests on your real home, Docker state, or projects. JSON-only catalogue additions follow the <a href="/kundol/registry.html">optimisation registry guide</a>.</p><h2 id="request-or-contribute-a-registry-target" tabindex="-1">Request or contribute a registry target <a class="header-anchor" href="#request-or-contribute-a-registry-target" aria-label="Permalink to &quot;Request or contribute a registry target&quot;">​</a></h2><ol><li>Run <code>kundol tools search &lt;query&gt;</code> for published targets and <code>kundol tools list</code> for the full catalogue; also search existing issues. The source definitions are in <a href="https://github.com/vikz91/kundol/blob/main/registry/optimisations.json" target="_blank" rel="noreferrer"><code>optimisations.json</code></a>.</li><li>Run <code>kundol tools request</code> to open a prefilled Markdown GitHub issue, or <a href="https://github.com/vikz91/kundol/issues/new?title=%5BRegistry%20request%5D%3A%20&amp;body=Owning%20tool%3A%0A%0AExact%20target%20and%20scope%3A%0A%0AOwner%20documentation%3A%0A%0AWhy%20add%20it%3A%0A%0AData%20and%20safety%20risks%3A%0A" target="_blank" rel="noreferrer">open the request directly</a>. Name the owning tool, exact generated path or resource and scope, owner-maintained documentation, expected benefit, and retention or data risks. Say when ownership or safety is uncertain; omit private paths, usernames, and secrets. The <a href="https://github.com/vikz91/kundol/blob/main/.github/ISSUE_TEMPLATE/registry_request.yml" target="_blank" rel="noreferrer">structured request form</a> is already on <code>main</code> and appears in GitHub&#39;s issue chooser.</li><li>Comment on the issue if you want to implement it. A maintainer can triage it, add <code>help wanted</code> or <code>good first issue</code>, and assign it. Reference the issue in your PR with <code>Closes #number</code>.</li></ol><p>To draft the first entry, run <code>bun run registry:new -- --help</code>. The command asks for a stable rule ID, existing category ID, short label/description, scope, and either an existing source reference or a new owner-documentation URL. It appends one valid <code>proposed</code> rule and source without reformatting the whole registry. The generated rule is <strong>protected inventory only</strong>: its selector is an unimplemented placeholder, <code>action</code> is <code>none</code>, and it cannot remove anything. Inspect <a href="/kundol/registry.html">the registry fields and safety policy</a>, replace the placeholder only when supported by precise owner evidence and code-owned adapters, then run <code>bun run registry:check</code> and <code>bun run check</code>.</p><p>For example, replace <code>ToolName</code> and the URL with an actual owner-documented target. <code>--dry-run</code> previews the addition; remove it to write the entry.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry:new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store.toolname.cache</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --category</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shared_stores</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ToolName cache&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --description</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Inventory ToolName&#39;s generated cache.&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toolname_cache</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --source-title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ToolName cache guide&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://owner.example/docs/cache&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dry-run</span></span></code></pre></div><p>In the PR, explain the exact target, source, selector, and safety tier. Ask a maintainer for the <code>registry</code> label. Once merged, the changelog automatically credits the PR author&#39;s GitHub handle; the linked request issue closes through the PR. A merged catalogue entry can remain <code>proposed</code> until its registry-backed CLI path exists.</p><h2 id="how-a-registry-rule-advances" tabindex="-1">How a registry rule advances <a class="header-anchor" href="#how-a-registry-rule-advances" aria-label="Permalink to &quot;How a registry rule advances&quot;">​</a></h2><p>The <code>status</code> on each JSON rule tracks <strong>registry-backed delivery</strong>, not the issue&#39;s progress. Move it through these phases in a reviewed PR with evidence for the next gate; merging an issue or PR does not advance it automatically.</p><table tabindex="0"><thead><tr><th>Phase</th><th>What the contributor must show</th><th>Availability</th></tr></thead><tbody><tr><td><code>proposed</code></td><td>Exact owner-documented target, scope, source reference, and conservative review policy. A scaffolded entry starts protected with <code>action: none</code>.</td><td>Catalogue research only; no registry-backed CLI behavior.</td></tr><tr><td><code>wip</code></td><td>An implementation PR or linked work item identifies the precise selector/probe, required code-owned adapters, live validators, action or inventory plan, and disposable tests being built. Keep unsupported handlers inactive.</td><td>Still unavailable to CLI users.</td></tr><tr><td><code>beta</code></td><td>Experimental testing catalogue. Executable beta additionally requires implemented handlers, live revalidation, audit, disposable safety tests, documentation, explicit opt-in, and a code-owned approval for that exact ID.</td><td>Catalogue-only until those gates pass; review and protected tiers still restrict actions.</td></tr><tr><td><code>published</code></td><td>Supported normal CLI flow, stable plan/output and failure behavior, regression and safety coverage, and maintained user documentation. A maintainer reviews the evidence and changes the rule status.</td><td>Available through the supported CLI path, subject to its safety tier and selection policy.</td></tr></tbody></table><p>The current registry is <code>engine_ready</code>, with 28 published and 69 beta catalogue rules. Normal optimisation loads published rules; <code>--allow-beta</code> admits only five exact code-approved beta bindings (Yarn Classic review, two Linux Python reviews, and two protected Docker inventories). A status change to <code>published</code> can enable a target when its selector, validator, action, owner marker, target kind, and review tier satisfy code-owned policies; review that change as executable behavior. The other 64 beta IDs remain inactive and are reported individually in their route. Missing handlers fail closed, and all 17 protected beta entries remain non-removing. See the <a href="/kundol/registry.html">registry guide</a> for selector, validator, and action contracts.</p><p>For other behavior changes or safety questions, open an issue. In a pull request, describe the trigger, resulting behavior, affected paths, and verification command. The <a href="https://github.com/vikz91/kundol/blob/main/.github/pull_request_template.md" target="_blank" rel="noreferrer">PR template</a> provides a short outline.</p><p>During an interactive <code>git commit</code>, the version hook asks for a major, minor, or patch bump and stages it in that same commit. Use <code>KUNDOL_VERSION_BUMP=skip</code> when a version change is intentionally inappropriate; non-interactive commits skip the prompt.</p>`,17)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
